import json
arts=json.load(open('data/articles.json',encoding='utf-8'))
roots={r['key']:r for r in json.load(open('data/taxonomy.json',encoding='utf-8'))['roots']}

def find(nodes,key):
    return next((n for n in nodes if (n.get('key') or '')==key), None)

def build_draft_from_path(sec, kind='', lv1='', lv2='', lv3=''):
    root=roots[sec]
    data={'section_key':sec,'section_label':root['label'],'section_href':sec+'.html','library_kind_key':'','library_kind_label':'','topic_lv1_key':'','topic_lv1_label':'','topic_lv2_key':'','topic_lv2_label':'','topic_lv3_key':'','topic_lv3_label':''}
    lv1s=root['children']
    if sec=='thu-vien':
        k=find(root['children'],kind); assert k
        data['library_kind_key']=kind; data['library_kind_label']=k['label']; lv1s=k.get('children',[])
    n1=find(lv1s,lv1); assert n1
    data['topic_lv1_key']=lv1; data['topic_lv1_label']=n1['label']
    n2=find(n1.get('children',[]),lv2); assert n2 is not None
    data['topic_lv2_key']=lv2; data['topic_lv2_label']=n2['label']
    if lv3:
        n3=find(n2.get('children',[]),lv3); assert n3
        data['topic_lv3_key']=lv3; data['topic_lv3_label']=n3['label']
    return data

def topic_label(t):
    return t.get('topic_lv2_label') or t.get('topic_lv3_label') or t.get('topic_lv1_label') or ''
def badge_label(t):
    return t.get('library_kind_label') if t.get('section_key')=='thu-vien' else (t.get('topic_lv1_label') or t.get('section_label') or '')

